const areas = [
  {id:'data-protection', name:'Data protection, privacy notices and data-subject rights'},
  {id:'consumer-contracts', name:'Consumer protection, unfair terms and electronic contracting'},
  {id:'cooperatives', name:'Cooperative societies and informal chama group records'},
  {id:'lending-credit', name:'Loans, credit services, microfinance and credit reporting'},
  {id:'payments', name:'Payment systems, M-Pesa and payment-service boundaries'},
  {id:'cybercrime-comms', name:'Cybercrime, electronic communications and online-service terms'}
];
const itemSchema = JSON.stringify({type:'object',properties:{area:{type:'string'},sources:{type:'array',items:{type:'object',properties:{title:{type:'string'},url:{type:'string'},authority:{type:'string'},sections:{type:'string'},relevant_rule:{type:'string'}},required:['title','url','authority','sections','relevant_rule']}},key_obligations:{type:'array',items:{type:'string'}},applicability_to_product:{type:'string'},policy_implications:{type:'array',items:{type:'string'}},open_facts:{type:'array',items:{type:'string'}}},required:['area','sources','key_obligations','applicability_to_product','policy_implications','open_facts']});
const findings = await parallel('Kenyan law research for Chama terms and privacy', () => areas.map(area => agent(
  'Research exactly this Kenyan-law area for a draft Terms and Conditions and Privacy Policy for Jirani Chama: ' + area.name + '. Use current authoritative primary sources, prioritizing Kenya Law (kenyalaw.org), ODPC, CBK, CAK, and official government sources. Search broadly, then open/fetch the actual sources; do not rely on snippets. Return only verified points with statute/regulation names, section/rule numbers, direct source URLs, and concise source-supported implications for a chama-recordkeeping web app. Product context: the app records group/member accounts, contributions, loans, approvals, attendance, messages, and audit history; it does not disburse loans or move members’ money; live payment processing/subscription billing is disabled. Distinguish clearly between law that applies to the app operator and rules that may apply to a registered chama, a lender, or a payment provider instead. Do not claim full compliance, do not invent operator facts, and identify questions the operator must answer before publication. As-of date: 11 November 2026. Return the requested structured object only.',
  {brief:'Research Kenyan law: ' + area.name, schema:itemSchema, sandbox:'shared', effort_level:'standard'}
)), {schema:itemSchema});
const successful = findings.filter(x => x.ok).map(x => x.value);
const failures = findings.map((x,i) => x.ok ? null : {area:areas[i].name, code:x.error.code, message:x.error.message}).filter(Boolean);
const synthesisSchema = JSON.stringify({type:'object',properties:{overall_scope:{type:'string'},legal_requirements_for_documents:{type:'array',items:{type:'string'}},rules_not_to_attribute_to_the_app_without_facts:{type:'array',items:{type:'string'}},material_operator_facts_missing:{type:'array',items:{type:'string'}},verified_sources:{type:'array',items:{type:'object',properties:{title:{type:'string'},url:{type:'string'},why_relevant:{type:'string'}},required:['title','url','why_relevant']}},research_gaps:{type:'array',items:{type:'string'}}},required:['overall_scope','legal_requirements_for_documents','rules_not_to_attribute_to_the_app_without_facts','material_operator_facts_missing','verified_sources','research_gaps']});
const synthesis = await agent('Synthesize the successful research results below into a cautious legal drafting brief for the parent writer. Do not draft final policy text. Use only facts supported by the sources provided; preserve applicability caveats, identify missing controller/deployment/retention facts, and list verified official sources with URLs. Never say the product is legally compliant or that these are all laws. Research results: ' + JSON.stringify(successful) + '\nFailed research units: ' + JSON.stringify(failures), {brief:'Synthesize Kenyan legal findings for policy drafting', schema:synthesisSchema, sandbox:'shared', effort_level:'standard'});
return {findings:successful, failures, synthesis:synthesis.ok ? synthesis.value : {error:synthesis.error}};

